fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    input
        .into_iter()
        .map(|(a, b)| {
            if a == b {
                0
            } else if a < b {
                let d = b - a;
                if d % 2 != 0 { 1 } else { 2 }
            } else {
                let d = a - b;
                if d % 2 == 0 { 1 } else { 2 }
            }
        })
        .collect()
}

